shellCommands.command:
mkdir -p /tmp/smoke && cat > /tmp/smoke/entry.tsx <<'EOF'
export {App} from '/home/sandbox/workspace/src/App';
export {HomePage} from '/home/sandbox/workspace/src/pages/HomePage';
export {NotesPage} from '/home/sandbox/workspace/src/pages/NotesPage';
export {AboutPage} from '/home/sandbox/workspace/src/pages/AboutPage';
export {NotFoundPage} from '/home/sandbox/workspace/src/pages/NotFoundPage';
export {ThemeProvider} from '@gravity-ui/uikit';
EOF
npx vite build --ssr /tmp/smoke/entry.tsx --outDir /tmp/smoke/out --logLevel error && cat > /tmp/smoke/run.mjs <<'EOF'
const store = {};
globalThis.window = {
  location: {hash: '#/notes'},
  localStorage: {getItem: (k) => store[k] ?? null, setItem: (k, v) => (store[k] = v)},
  matchMedia: () => ({matches: true}),
  addEventListener() {}, removeEventListener() {},
};
const React = (await import('react')).default;
const {renderToString} = await import('react-dom/server');
const m = await import('/tmp/smoke/out/entry.mjs');
const wrap = (el) => renderToString(React.createElement(m.ThemeProvider, {theme: 'dark'}, el));
const check = (name, html, ...needles) => {
  const miss = needles.filter((n) => !html.includes(n));
  console.log(miss.length ? `FAIL ${name}: missing ${miss}` : `ok   ${name}`);
};
const app = renderToString(React.createElement(m.App));
check('App (server snapshot → home)', app, 'Добро пожаловать', 'Активна тёмная тема', 'aria-current="page"', 'href="#/notes"', 'Включить светлую тему', 'Сейчас заметок: 2');
check('Notes', wrap(React.createElement(m.NotesPage, {notes: [{id: 1, text: 'abc'}], onAdd() {}, onRemove() {}})), 'abc', 'Удалить «abc»', 'Новая заметка');
check('Notes empty', wrap(React.createElement(m.NotesPage, {notes: [], onAdd() {}, onRemove() {}})), 'Пока пусто');
check('About', wrap(React.createElement(m.AboutPage)), 'Hash-роутинг');
check('404', wrap(React.createElement(m.NotFoundPage)), 'Страница не найдена', 'href="#/"');
EOF
node /tmp/smoke/run.mjs

mkdir -p .smoke && sed 's#/home/sandbox/workspace/src#../src#' /tmp/smoke/entry.tsx > .smoke/entry.tsx && npx vite build --ssr .smoke/entry.tsx --outDir .smoke/out --logLevel error && cat > .smoke/run.mjs <<'EOF'
